// UnmarshalText implements the [encoding.TextUnmarshaler] interface.
func (s *MCPState) UnmarshalText(data []byte) error {
	switch string(data) {
	case "disabled":
		*s = MCPStateDisabled
	case "starting":
		*s = MCPStateStarting
	case "connected":
		*s = MCPStateConnected
	case "error":
		*s = MCPStateError
	case "needs auth":
		*s = MCPStateNeedsAuth
	default:
		return fmt.Errorf("unknown mcp state: %s", data)
	}
	return nil
}

