// UnmarshalJSON implements the json.Unmarshaler interface. This is needed
// because the Params field is of type any, so we need to unmarshal it into
// its appropriate type based on the [PermissionRequest.ToolName].
func (p *PermissionRequest) UnmarshalJSON(data []byte) error {
	type Alias PermissionRequest
	aux := &struct {
		Params json.RawMessage `json:"params"`
		*Alias
	}{
		Alias: (*Alias)(p),
	}
	if err := json.Unmarshal(data, &aux); err != nil {
		return err
	}

	params, err := unmarshalToolParams(p.ToolName, aux.Params)
	if err != nil {
		return err
	}
	p.Params = params
	return nil
}

// UnmarshalJSON implements the json.Unmarshaler interface. This is needed
// because the Params field is of type any, so we need to unmarshal it into
// its appropriate type based on the [CreatePermissionRequest.ToolName].
func (p *CreatePermissionRequest) UnmarshalJSON(data []byte) error {
	type Alias CreatePermissionRequest
	aux := &struct {
		Params json.RawMessage `json:"params"`
		*Alias
	}{
		Alias: (*Alias)(p),
	}
	if err := json.Unmarshal(data, &aux); err != nil {
		return err
	}

	params, err := unmarshalToolParams(p.ToolName, aux.Params)
	if err != nil {
		return err
	}
	p.Params = params
	return nil
}
func unmarshalToolParams(toolName string, raw json.RawMessage) (any, error) {
	switch toolName {
	case BashToolName:
		var params ProtoBashPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case DownloadToolName:
		var params ProtoDownloadPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case EditToolName:
		var params ProtoEditPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case WriteToolName:
		var params ProtoWritePermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case MultiEditToolName:
		var params ProtoMultiEditPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case FetchToolName:
		var params ProtoFetchPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case AgenticFetchToolName:
		var params ProtoAgenticFetchPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case ViewToolName:
		var params ProtoViewPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	case LSToolName:
		var params ProtoLSPermissionsParams
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, err
		}
		return params, nil
	default:
		// For unknown tools, keep the raw JSON as-is.
		var generic map[string]any
		if err := json.Unmarshal(raw, &generic); err != nil {
			return nil, err
		}
		return generic, nil
	}
}

