type sseSink struct {
	stateMu sync.Mutex
	writeMu sync.Mutex
	ctx     context.Context
	w       http.ResponseWriter
	f       *http.ResponseController
	frame   string
	closed  bool
}

func (s *sseSink) Send(ctx context.Context, event SSEEvent) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	s.stateMu.Lock()
	closed := s.closed
	s.stateMu.Unlock()
	if closed {
		return fmt.Errorf("SSE stream is closed")
	}
	if err := s.ctx.Err(); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if deadline, ok := ctx.Deadline(); ok {
		if err := s.f.SetWriteDeadline(deadline); err != nil {
			return err
		}
		defer s.f.SetWriteDeadline(time.Time{})
	}
	b, err := json.Marshal(event)
	if err != nil {
		return err
	}
	if _, err = fmt.Fprintf(s.w, s.frame, b); err != nil {
		return err
	}
	if err := s.f.Flush(); err != nil {
		return err
	}
	return nil
}
func (s *sseSink) Close(err error) error {
	s.stateMu.Lock()
	s.closed = true
	s.stateMu.Unlock()
	return err
}

