	private.HandleFunc("GET /v1/workspaces/{id}/events", func(w http.ResponseWriter, req *http.Request) {
		if !requireEmptyRequestBody(w, req, maxBodyBytes, 400, "failed to decode request") {
			return
		}
		input := OperationSubscribeEventsRequest{Header: req.Header.Clone()}
		input.ID = req.PathValue("id")
		input.Query.ClientID = req.URL.Query().Get("client_id")
		if input.Query.ClientID == "" {
			writeSourceError(w, 400, "client_id is required")
			return
		}
		if _, err := uuid.Parse(input.Query.ClientID); err != nil {
			writeSourceError(w, 400, "client_id is not a valid UUID")
			return
		}
		producer, err := impl.SubscribeEvents(req.Context(), input)
		if err != nil {
			if !WriteHTTPError(w, err) {
				writeSourceError(w, http.StatusInternalServerError, err.Error())
			}
			return
		}
		if producer == nil {
			writeSourceError(w, http.StatusInternalServerError, "nil event producer")
			return
		}
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		w.WriteHeader(200)
		f := http.NewResponseController(w)
		_ = f.Flush()
		sink := &sseSink{ctx: req.Context(), w: w, f: f, frame: "data: %s\n\n"}
		err = producer.Serve(req.Context(), sink)
		if err != nil && req.Context().Err() == nil {
			_ = sink.Close(err)
			return
		}
		_ = sink.Close(nil)
	})
