func bodyLimit(options RegistrationOptions) (int64, error) {
	if options.MaxBodyBytes == 0 {
		return DefaultMaxBodyBytes, nil
	}
	if options.MaxBodyBytes < 0 {
		return 0, fmt.Errorf("clientserver: MaxBodyBytes must be positive")
	}
	return options.MaxBodyBytes, nil
}
func authorize(options RegistrationOptions, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		if err := options.Authenticator.Authenticate(req.Context(), req.Header.Clone()); err != nil {
			var httpErr *HTTPError
			if errors.As(err, &httpErr) && httpErr.Status == http.StatusUnauthorized && (httpErr.Header == nil || httpErr.Header.Get("WWW-Authenticate") == "") {
				w.Header().Set("WWW-Authenticate", "Bearer")
			}
			if !WriteHTTPError(w, err) {
				w.Header().Set("WWW-Authenticate", "Bearer")
				http.Error(w, err.Error(), http.StatusUnauthorized)
			}
			return
		}
		next.ServeHTTP(w, req)
	})
}
func allowQuery(values map[string][]string, allowed []string) bool {
	for key := range values {
		valid := false
		for _, allowedKey := range allowed {
			if key == allowedKey {
				valid = true
				break
			}
		}
		if !valid {
			return false
		}
	}
	return true
}

var errRequestBodyTooLarge = errors.New("request body too large")

const requestBodyTooLargeMessage = "request body too large"

func decodeRequestJSON(w http.ResponseWriter, req *http.Request, dst any, max int64, sourceStatus int, sourceMessage string) bool {
	if err := decodeJSON(w, req, dst, max); err != nil {
		if errors.Is(err, errRequestBodyTooLarge) {
			writeSourceError(w, http.StatusRequestEntityTooLarge, requestBodyTooLargeMessage)
		} else {
			writeSourceError(w, sourceStatus, sourceMessage)
		}
		return false
	}
	return true
}
func decodeJSON(w http.ResponseWriter, req *http.Request, dst any, max int64) error {
	if req.Body == nil || req.ContentLength == 0 {
		return fmt.Errorf("missing request body")
	}
	if req.ContentLength > max {
		return errRequestBodyTooLarge
	}
	body := http.MaxBytesReader(w, req.Body, max)
	decoder := json.NewDecoder(body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return errRequestBodyTooLarge
		}
		return fmt.Errorf("failed to decode request: %w", err)
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return errRequestBodyTooLarge
		}
		return fmt.Errorf("failed to decode request")
	}
	return nil
}
func requireEmptyRequestBody(w http.ResponseWriter, req *http.Request, max int64, sourceStatus int, sourceMessage string) bool {
	if req.Body == nil || req.ContentLength == 0 {
		return true
	}
	body := http.MaxBytesReader(w, req.Body, max)
	data, err := io.ReadAll(body)
	if err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			writeSourceError(w, http.StatusRequestEntityTooLarge, requestBodyTooLargeMessage)
			return false
		}
		writeSourceError(w, sourceStatus, sourceMessage)
		return false
	}
	if len(data) != 0 {
		writeSourceError(w, sourceStatus, sourceMessage)
		return false
	}
	return true
}
func requireEmptyBody(req *http.Request) error {
	if req.Body != nil && req.ContentLength != 0 {
		return fmt.Errorf("request body is not accepted")
	}
	return nil
}
func defaultStatus(status int, accepted []int) int {
	if status != 0 {
		return status
	}
	if len(accepted) != 0 {
		return accepted[0]
	}
	return http.StatusOK
}
func applyResponseMetadata(w http.ResponseWriter, metadata ResponseMetadata) {
	if metadata.Header != nil {
		for key, values := range metadata.Header {
			for _, value := range values {
				w.Header().Add(key, value)
			}
		}
	}
}
func writeEmpty(w http.ResponseWriter, status int, metadata ResponseMetadata, accepted []int) {
	applyResponseMetadata(w, metadata)
	w.WriteHeader(defaultStatus(status, accepted))
}
func writeJSON(w http.ResponseWriter, status int, metadata ResponseMetadata, accepted []int, value any) {
	applyResponseMetadata(w, metadata)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(defaultStatus(status, accepted))
	_ = json.NewEncoder(w).Encode(value)
}
func writeSourceError(w http.ResponseWriter, status int, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(Error{Message: message})
}

// EventEnvelope is the stock SSE outer wire envelope. Payload is decoded only
// through DecodeEvent into one of the closed concrete SSEEvent variants.
type EventEnvelope struct {
	Type    EventType       `json:"type"`
	Payload json.RawMessage `json:"payload"`
}

